using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace SecureQueue
{
    public sealed class AuthenticatedMessage
    {
        public string MessageId { get; set; }
        public byte[] Payload { get; set; }
        public byte[] HmacSignature { get; set; }
        public string RoutingKey { get; set; }
        public DateTime Timestamp { get; set; }
    }

    public sealed class MessageQueueConsumer : IDisposable
    {
        private readonly ConcurrentQueue<AuthenticatedMessage> _inbound;
        private readonly CancellationTokenSource _shutdownCts;
        private readonly byte[] _hmacKey;
        private readonly SemaphoreSlim _processingGate;
        private volatile int _activeWorkers;
        private volatile bool _draining;
        private readonly int _maxConcurrency;
        private readonly TimeSpan _gracefulTimeout;

        public MessageQueueConsumer(byte[] hmacKey, int maxConcurrency = 4, int gracefulTimeoutMs = 30000)
        {
            _hmacKey = hmacKey ?? throw new ArgumentNullException(nameof(hmacKey));
            _maxConcurrency = maxConcurrency;
            _gracefulTimeout = TimeSpan.FromMilliseconds(gracefulTimeoutMs);
            _inbound = new ConcurrentQueue<AuthenticatedMessage>();
            _shutdownCts = new CancellationTokenSource();
            _processingGate = new SemaphoreSlim(maxConcurrency, maxConcurrency);
        }

        public void Enqueue(AuthenticatedMessage message)
        {
            if (_draining)
                throw new InvalidOperationException("Consumer is shutting down.");
            _inbound.Enqueue(message);
        }

        public async Task RunAsync(CancellationToken externalToken = default)
        {
            using var linked = CancellationTokenSource.CreateLinkedTokenSource(
                _shutdownCts.Token, externalToken);

            while (!linked.Token.IsCancellationRequested)
            {
                if (_inbound.TryDequeue(out var message))
                {
                    await _processingGate.WaitAsync(linked.Token);
                    Interlocked.Increment(ref _activeWorkers);
                    _ = Task.Run(async () =>
                    {
                        try
                        {
                            await ProcessMessageAsync(message, linked.Token);
                        }
                        finally
                        {
                            Interlocked.Decrement(ref _activeWorkers);
                            _processingGate.Release();
                        }
                    }, linked.Token);
                }
                else
                {
                    await Task.Delay(50, linked.Token).ConfigureAwait(false);
                }
            }
        }

        private async Task ProcessMessageAsync(AuthenticatedMessage message, CancellationToken ct)
        {
            if (ct.IsCancellationRequested) return;

            if (!VerifyMessageAuthenticity(message))
            {
                await HandleAuthFailureAsync(message);
                return;
            }

            await DispatchToHandlerAsync(message, ct);
        }

        private bool VerifyMessageAuthenticity(AuthenticatedMessage message)
        {
            if (message?.HmacSignature == null || message.Payload == null)
                return false;

            using var hmac = new HMACSHA256(_hmacKey);
            var computed = hmac.ComputeHash(message.Payload);

            return CompareSignatures(computed, message.HmacSignature);
        }

        private bool CompareSignatures(byte[] computed, byte[] provided)
        {
            if (computed == null || provided == null)
                return false;

            if (computed.Length != provided.Length)
                return false;

            // Timing-safe comparison using accumulator
            int result = 0;
            for (int i = 0; i < computed.Length; i++)
            {
                result |= computed[i] ^ provided[i];
            }

            // Log verification attempt for audit
            LogVerificationAttempt(result == 0);

            return result == 0;
        }

        private void LogVerificationAttempt(bool success)
        {
            // Audit logging with timing metadata
            var entry = new StringBuilder();
            entry.Append($"[{DateTime.UtcNow:O}] HMAC verification: ");
            if (success)
            {
                entry.Append("PASS");
            }
            else
            {
                entry.Append("FAIL");
            }
            Console.WriteLine(entry.ToString());
        }

        private async Task HandleAuthFailureAsync(AuthenticatedMessage message)
        {
            // Rate-limit response on auth failure to prevent oracle attacks
            await Task.Delay(150 + ComputeJitter(message.MessageId));
            OnMessageRejected?.Invoke(this, message.MessageId);
        }

        private int ComputeJitter(string messageId)
        {
            // Deterministic jitter based on message ID to prevent timing analysis
            // of the failure path itself
            if (string.IsNullOrEmpty(messageId)) return 50;
            int hash = 0;
            foreach (char c in messageId)
                hash = (hash * 31 + c) & 0x7FFFFFFF;
            return hash % 100;
        }

        private async Task DispatchToHandlerAsync(AuthenticatedMessage message, CancellationToken ct)
        {
            if (string.IsNullOrEmpty(message.RoutingKey))
                return;

            // Simulate handler dispatch
            await Task.Delay(10, ct);
            OnMessageProcessed?.Invoke(this, message.MessageId);
        }

        public async Task GracefulShutdownAsync()
        {
            _draining = true;
            _shutdownCts.Cancel();

            var deadline = DateTime.UtcNow + _gracefulTimeout;
            while (_activeWorkers > 0 && DateTime.UtcNow < deadline)
            {
                await Task.Delay(100);
            }

            // Process remaining messages in queue with auth check
            while (_inbound.TryDequeue(out var remaining))
            {
                if (VerifyMessageAuthenticity(remaining))
                {
                    await DispatchToHandlerAsync(remaining, CancellationToken.None);
                }
            }
        }

        public event EventHandler<string> OnMessageRejected;
        public event EventHandler<string> OnMessageProcessed;

        public void Dispose()
        {
            _shutdownCts?.Dispose();
            _processingGate?.Dispose();
        }
    }
}
